  v_question record;
begin
  select id into v_catalog_id
    from public.learning_curriculum_catalogs
   where code = 'TECESCOLA_CORE' and version = '1.0'
   limit 1;
  if v_catalog_id is null then raise exception 'V5_CONTENT_CATALOG_MISSING'; end if;
  select id into v_skill_id
    from public.learning_curriculum_skills
   where catalog_id = v_catalog_id and code = 'BIOLOGY_ECOSYSTEM_INTERACTIONS';
  if v_skill_id is null then raise exception 'V5_CONTENT_SKILL_MISSING'; end if;

  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 5, 'Ler as relações de um ecossistema com evidências', 'Ecossistemas reúnem componentes bióticos e abióticos. Para explicar mudanças, acompanhe relações, matéria e energia, compare condições e limite a conclusão ao que os dados permitem.', '## 1. O sistema e seus componentes
Um ecossistema inclui os organismos de uma área e as condições físicas e químicas com as quais interagem. Organismos e suas relações são componentes bióticos; luz, água, temperatura, salinidade e características do solo são exemplos de fatores abióticos. Uma condição pode afetar espécies de formas diferentes: a resposta depende de suas necessidades, tolerâncias e das demais relações presentes.

## 2. Relações entre organismos
Na competição, organismos disputam um recurso limitado; apenas viver no mesmo lugar não prova competição. Na predação e na herbivoria, um organismo consome outro ou parte dele. No mutualismo, há benefício para ambos; no parasitismo, o parasita obtém benefício e o hospedeiro é prejudicado. Em uma teia alimentar, uma espécie pode ter mais de uma relação, então retirar um componente pode produzir efeitos indiretos e não necessariamente previsíveis com uma única seta.

## 3. Matéria e energia
A energia entra sobretudo pela produção primária e é transferida entre níveis tróficos; em cada transferência, parte é usada no metabolismo e dissipada como calor. A matéria não segue esse mesmo percurso: elementos podem circular entre organismos, água, ar e solo. Decompositores transformam matéria orgânica e participam dessa circulação. Por isso, desenhe fluxo de energia e ciclos de matéria de maneiras distintas.

## 4. Como sustentar uma explicação
Uma observação registra o que foi medido; uma hipótese propõe um mecanismo. Se uma população muda depois de uma estiagem, isso não prova, sozinho, que a estiagem foi a única causa. Compare séries temporais, locais de referência, esforço de amostragem e outras condições, como temperatura, oxigênio e alimento. Uma conclusão científica pode ser útil sem ser absoluta: declare a evidência, a explicação compatível e o que ainda precisaria ser medido.',
    'Em dois trechos de um riacho, pesquisadores medem a temperatura e contam macroinvertebrados em vários dias. No trecho próximo a uma área sem sombra, a temperatura sobe e a contagem de alguns grupos cai; no trecho sombreado, ambas variam pouco. Primeiro, descreva os dados observados. Depois, formule a hipótese de que o aquecimento contribuiu para a mudança. Por fim, verifique se vazão, oxigênio dissolvido, poluição e esforço de coleta também foram comparados. O padrão apoia a hipótese, mas não autoriza atribuir o resultado a uma causa única sem controlar alternativas.', array['Classifique primeiro o que foi medido: organismo, interação ou condição abiótica.', 'Desenhe setas de energia e ciclos de matéria separadamente.', 'Ao explicar uma mudança, procure mecanismo, comparação e explicações alternativas.', 'Não generalize um indivíduo ou um ponto de coleta para toda a população sem amostragem adequada.']::text[], 12, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v5-biology-ecosystem-interactions","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Distinguir seres vivos de condições físicas e químicas do ambiente.","Ler comparações simples entre grupos, locais ou momentos."],"key_concepts":["Componentes bióticos e abióticos interagem.","Interações incluem competição, predação, herbivoria, mutualismo e parasitismo.","Energia flui pelas relações tróficas; matéria circula entre organismos e ambiente.","A força de uma conclusão depende do desenho de observação e das alternativas consideradas."],"progression":[{"stage":"FOUNDATION","focus":"Classificar componentes e reconhecer relações explícitas.","questionIds":["v5-bio-eco-probe-01","v5-bio-eco-probe-02"]},{"stage":"APPLICATION","focus":"Explicar mecanismos em redes alimentares, recursos e decomposição.","questionIds":["v5-bio-eco-practice-01","v5-bio-eco-practice-08"]},{"stage":"TRANSFER","focus":"Aplicar o raciocínio a ambientes e dados novos, considerando controles e alternativas.","questionIds":["v5-bio-eco-transfer-01","v5-bio-eco-transfer-06"]},{"stage":"INTEGRATION","focus":"Distinguir níveis ecológicos, fluxos e limites de inferência.","questionIds":["v5-bio-eco-lock-01","v5-bio-eco-lock-04"]},{"stage":"SPACED_REVIEW_CANDIDATE","focus":"Retomar ideias centrais em contextos distintos; espaçamento ainda depende do agendador do produto.","questionIds":["v5-bio-eco-review-01","v5-bio-eco-review-08"]}],"micro_explanations":[{"trigger":"CLASSIFICATION_ERROR","text":"Pergunte se o elemento é um organismo ou uma condição física/química. A interação entre ambos pode ser a explicação, mas não muda sua classificação."},{"trigger":"ENERGY_MATTER_CONFUSION","text":"Siga uma parcela de energia até o uso metabólico e o calor; depois siga um elemento da matéria, que pode passar entre organismos e ambiente."},{"trigger":"CAUSALITY_OVERCLAIM","text":"Separe o registro observado da hipótese. Procure uma comparação que ajude a afastar outras explicações."},{"trigger":"LEVEL_OF_ORGANIZATION_ERROR","text":"Um indivíduo é um organismo; indivíduos da mesma espécie formam uma população; várias populações formam uma comunidade; o ecossistema inclui também fatores abióticos."}],"remediations":[{"misconception":"BIOTIC_ABIOTIC_MIXUP","prompt":"Monte duas colunas: organismos/interações e condições físicas/químicas. Depois conecte um elemento de cada coluna com uma relação observável."},{"misconception":"ENERGY_AND_MATTER_SAME_PATH","prompt":"Desenhe uma seta de energia entre níveis tróficos e um ciclo para um nutriente; marque onde há transferência e onde há retorno ao ambiente."},{"misconception":"CORRELATION_PROVES_SINGLE_CAUSE","prompt":"Liste o que foi medido, a hipótese e duas variáveis alternativas. Indique que comparação adicional diferenciaria as explicações."},{"misconception":"INDIVIDUAL_EQUALS_POPULATION","prompt":"Identifique a unidade observada e proponha uma amostra que represente a população em mais de um local ou momento."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"title":"Ecological Processes","publisher":"U.S. Environmental Protection Agency","url":"https://www.epa.gov/report-environment/ecological-processes","accessedOn":"2026-10-13","supports":["primary production","carbon and nutrient cycling","ecosystem stressors","repeated measurement and limits of indicators"],"use":"Scientific fact-check only; wording, examples, questions and explanations in this package are original."}],"copyright_note":"No source wording, questions, figures or data were copied. Scenarios and values are hypothetical and authored for this package.","objective":"Relacionar organismos, interações e condições físicas ou químicas de um ecossistema, distinguindo observações de hipóteses causais.","common_mistake":"Confundir coincidência temporal com prova de causa, tratar toda relação alimentar como uma cadeia simples ou dizer que energia e matéria são recicladas do mesmo modo.","estimated_minutes":12}'::jsonb
  ) on conflict (canonical_skill_id, version) do nothing;
  select id into v_lesson_id from public.learning_skill_lessons
   where canonical_skill_id = v_skill_id and version = 5
     and metadata->>'content_id' = 'v5-biology-ecosystem-interactions' and active = false;
  if v_lesson_id is null then raise exception 'V5_CONTENT_LESSON_CONFLICT'; end if;

  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-bio-eco-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"CLASSIFY","contextFamily":"SALINIDADE_ESTUARIO","statement":"Em uma medição de estuário, pesquisadores registram salinidade da água e presença de caranguejos. Como esses dois elementos são classificados?","options":["Salinidade é abiótica e caranguejos são bióticos.","Salinidade é biótica porque afeta seres vivos; caranguejos são abióticos.","Os dois são bióticos porque foram medidos no mesmo local.","Os dois são abióticos porque fazem parte da água."],"correctAnswer":"Salinidade é abiótica e caranguejos são bióticos.","explanation":"Salinidade é uma condição química do ambiente; caranguejos são organismos. Uma condição abiótica pode influenciar organismos sem se tornar biótica.","hint":"Classifique cada item pelo que ele é, não pelo efeito que pode causar.","errorFocus":"BIOTIC_ABIOTIC_MIXUP","misconceptions":{"Salinidade é biótica porque afeta seres vivos; caranguejos são abióticos.":["EFFECT_CONFUSED_WITH_COMPONENT_TYPE"]},"position":1},{"id":"v5-bio-eco-probe-02","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"INTERPRET","contextFamily":"TEIA_DE_BREJO","statement":"Em um esquema, uma seta vai de uma planta aquática para um caramujo que se alimenta dela. O que a seta representa nesse modelo alimentar?","options":["A direção em que a planta consome o caramujo.","Que a planta depende do caramujo para realizar fotossíntese.","Que a quantidade de indivíduos das duas espécies é igual.","A direção de transferência de matéria e energia alimentar da planta para o consumidor."],"correctAnswer":"A direção de transferência de matéria e energia alimentar da planta para o consumidor.","explanation":"Na convenção usual de teias alimentares, a seta aponta do recurso consumido para o consumidor, representando a transferência pela alimentação.","hint":"Pergunte qual organismo serve de alimento e qual o consome.","errorFocus":"FOOD_WEB_ARROW_REVERSED","misconceptions":{"A direção em que a planta consome o caramujo.":["FOOD_WEB_ARROW_REVERSED"]},"position":2},{"id":"v5-bio-eco-practice-01","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"EXPLAIN","contextFamily":"DECOMPOSICAO_FOLHICA","statement":"Em uma área de mata, folhas caídas são fragmentadas por pequenos animais e transformadas por fungos e bactérias. Qual interpretação relaciona melhor esse processo ao ecossistema?","options":["A energia volta intacta às folhas e dispensa a luz solar.","A decomposição interrompe qualquer circulação de nutrientes.","Fungos e bactérias convertem matéria em energia que permanece sem perdas.","A matéria orgânica é transformada e elementos podem retornar ao ambiente; isso não significa que a energia seja reciclada integralmente."],"correctAnswer":"A matéria orgânica é transformada e elementos podem retornar ao ambiente; isso não significa que a energia seja reciclada integralmente.","explanation":"Decompositores participam da transformação da matéria orgânica e da circulação de elementos. Energia, por outro lado, é transferida e parte se dissipa como calor.","hint":"Siga separadamente um elemento químico e a energia armazenada na matéria orgânica.","errorFocus":"ENERGY_AND_MATTER_SAME_PATH","misconceptions":{"A energia volta intacta às folhas e dispensa a luz solar.":["ENERGY_RECYCLED_AS_MATTER"]},"position":1},{"id":"v5-bio-eco-practice-02","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"SOMBRA_E_PRODUCAO","statement":"Em um experimento de vasos, plantas da mesma espécie recebem igual água e solo; metade fica sob sombra intensa. Após alguns dias, o grupo sombreado apresenta menor crescimento. Qual conclusão é mais compatível com o desenho?","options":["A diferença é compatível com efeito da luz no crescimento, embora o resultado dependa de como as demais condições foram mantidas.","A sombra prova que a água nunca influencia o crescimento de plantas.","A menor altura demonstra que todas as plantas morreram por falta de nutrientes.","Como os vasos são da mesma espécie, o resultado não pode envolver fator abiótico."],"correctAnswer":"A diferença é compatível com efeito da luz no crescimento, embora o resultado dependa de como as demais condições foram mantidas.","explanation":"A comparação controlada torna a luz uma explicação plausível, mas a interpretação requer verificar se os grupos diferiram apenas na condição planejada e se houve replicação suficiente.","hint":"Identifique a variável alterada e quais condições precisariam permanecer comparáveis.","errorFocus":"EXPERIMENTAL_CONTROL_IGNORED","misconceptions":{"A sombra prova que a água nunca influencia o crescimento de plantas.":["ONE_FACTOR_EXCLUDES_ALL_OTHERS"]},"position":2},{"id":"v5-bio-eco-practice-03","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"COMPETICAO_POR_AGUA","statement":"Duas espécies de gramíneas ocupam o mesmo canteiro. Em parcelas com pouca água, a remoção de uma delas é seguida por maior crescimento da outra; com irrigação abundante, a diferença quase desaparece. Qual hipótese é mais consistente?","options":["As espécies mantêm mutualismo obrigatório em qualquer condição.","A água é um componente biótico que uma espécie oferece à outra.","A disponibilidade limitada de água pode intensificar a competição entre as espécies.","O crescimento prova que a espécie removida era predadora da gramínea restante."],"correctAnswer":"A disponibilidade limitada de água pode intensificar a competição entre as espécies.","explanation":"A resposta à remoção depende da disponibilidade do recurso e é compatível com competição por água. O padrão não prova que esse seja o único mecanismo sem medidas adicionais.","hint":"Compare o resultado quando o recurso é escasso com o resultado quando é abundante.","errorFocus":"RESOURCE_LIMITATION_IGNORED","misconceptions":{"A água é um componente biótico que uma espécie oferece à outra.":["ABIOTIC_RESOURCE_MISCLASSIFIED"]},"position":3},{"id":"v5-bio-eco-practice-04","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"PREDICT","contextFamily":"PREDACAO_LAGOA","statement":"Em uma lagoa, peixes predadores consomem pequenos peixes que se alimentam de zooplâncton. Se a abundância dos predadores cair, qual previsão deve ser tratada como hipótese a testar, não como certeza?","options":["A população pode aumentar, mas alimento, abrigo e outras relações também podem limitar essa resposta.","A população de pequenos peixes pode aumentar se a predação for limitante, mas outros fatores podem compensar a mudança.","A população ficará necessariamente igual, pois predadores não afetam suas presas quando há outros recursos.","O zooplâncton necessariamente diminuirá antes de qualquer mudança nos peixes."],"correctAnswer":"A população pode aumentar, mas alimento, abrigo e outras relações também podem limitar essa resposta.","explanation":"A redução de predadores pode aliviar a pressão de predação, mas populações respondem a vários fatores e a rede pode produzir efeitos indiretos.","hint":"Siga uma relação direta e depois liste outros fatores que afetam a população.","errorFocus":"SINGLE_LINK_DETERMINISM","misconceptions":{"A população ficará necessariamente igual, pois predadores não afetam suas presas quando há outros recursos.":["PREDATION_EFFECT_IGNORED"]},"position":4},{"id":"v5-bio-eco-practice-05","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"NUTRIENTES_COSTEIROS","statement":"Após aumento de nutrientes em uma enseada, sensores registram maior crescimento de algas e, dias depois, menos oxigênio dissolvido. Qual mecanismo é uma explicação plausível para a sequência?","options":["O oxigênio dissolvido é transformado em luz pelas algas e deixa de existir.","Nutrientes eliminam decompositores, impedindo qualquer consumo de oxigênio.","As algas retiram todo o sal da água, causando diretamente a queda do oxigênio.","A produção elevada pode gerar mais matéria orgânica; sua decomposição consome oxigênio da água."],"correctAnswer":"A produção elevada pode gerar mais matéria orgânica; sua decomposição consome oxigênio da água.","explanation":"Uma carga excessiva de nutrientes pode favorecer produção elevada; a decomposição da matéria orgânica pode reduzir o oxigênio dissolvido. A sequência observada é compatível com esse mecanismo e pode ser investigada com medidas adicionais.","hint":"Considere o que acontece com a matéria orgânica produzida quando ela morre e é decomposta.","errorFocus":"NUTRIENT_PRODUCTION_DECOMPOSITION_LINK","misconceptions":{"Nutrientes eliminam decompositores, impedindo qualquer consumo de oxigênio.":["DECOMPOSERS_EXCLUDED_FROM_CYCLE"]},"position":5},{"id":"v5-bio-eco-practice-06","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"CLASSIFY","contextFamily":"FIXACAO_NITROGENIO_SOLO","statement":"Em raízes de uma planta, bactérias vivem em associação e transformam compostos de nitrogênio em formas que podem entrar em processos biológicos. Qual leitura é mais cuidadosa?","options":["O nitrogênio é energia e por isso não pode circular entre solo e organismos.","Como as bactérias são microscópicas, elas são fatores abióticos.","Há uma interação entre organismos ligada à transformação de matéria; o benefício para cada parceiro deve ser avaliado pelas evidências do caso.","A associação prova, sem dados, que ambos os parceiros sempre recebem o mesmo benefício."],"correctAnswer":"Há uma interação entre organismos ligada à transformação de matéria; o benefício para cada parceiro deve ser avaliado pelas evidências do caso.","explanation":"Bactérias são componentes bióticos, e transformações de nitrogênio integram ciclos de matéria. A descrição da associação, sozinha, não basta para atribuir intensidade ou simetria de benefício.","hint":"Separe a classificação dos organismos da conclusão sobre o tipo de interação.","errorFocus":"INTERACTION_LABEL_WITHOUT_EVIDENCE","misconceptions":{"A associação prova, sem dados, que ambos os parceiros sempre recebem o mesmo benefício.":["MUTUALISM_ASSUMED_FROM_COLOCATION"]},"position":6},{"id":"v5-bio-eco-practice-07","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"POLINIZACAO_MATA","statement":"Em flores visitadas por insetos, observam-se grãos de pólen aderidos ao corpo dos visitantes e maior formação de frutos em flores acessíveis a eles. Qual interpretação distingue melhor evidência de conclusão?","options":["Os dados apoiam participação dos visitantes na polinização; para chamar a relação de benefício mútuo, também é preciso evidência sobre efeitos nos insetos.","Os dados provam que todos os visitantes recebem alimento de todas as flores.","A formação de frutos demonstra que os insetos são fatores abióticos.","A presença de pólen prova que nenhuma outra forma de polinização ocorre."],"correctAnswer":"Os dados apoiam participação dos visitantes na polinização; para chamar a relação de benefício mútuo, também é preciso evidência sobre efeitos nos insetos.","explanation":"Os registros apoiam uma contribuição para a reprodução das plantas. Mutualismo requer evidência de benefício para ambos, e a observação não exclui outros agentes.","hint":"Pergunte quais efeitos foram medidos para a planta e quais para o inseto.","errorFocus":"ONE_PARTNER_BENEFIT_AS_MUTUALISM_PROOF","misconceptions":{"Os dados provam que todos os visitantes recebem alimento de todas as flores.":["UNMEASURED_BENEFIT_ASSUMED"]},"position":7},{"id":"v5-bio-eco-practice-08","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"NITROGENIO_PRODUTIVIDADE","statement":"Em duas parcelas de um mesmo campo, a adição de um nutriente aumenta a biomassa vegetal apenas na parcela em que esse nutriente estava inicialmente escasso. O que o resultado sugere?","options":["Todo nutriente sempre aumenta a produção em qualquer quantidade e ecossistema.","A disponibilidade do nutriente pode limitar a produção naquele contexto, mas a limitação não precisa ser igual em todo o campo.","O nutriente é um organismo porque sua adição alterou plantas.","A biomassa vegetal mede diretamente toda a energia que entra no ecossistema."],"correctAnswer":"A disponibilidade do nutriente pode limitar a produção naquele contexto, mas a limitação não precisa ser igual em todo o campo.","explanation":"A resposta diferente entre parcelas é compatível com limitação por disponibilidade local. O resultado não autoriza extrapolar para qualquer quantidade ou sistema.","hint":"Compare a resposta à adição nas duas condições iniciais.","errorFocus":"LIMITING_FACTOR_GENERALIZED_UNIVERSALLY","misconceptions":{"Todo nutriente sempre aumenta a produção em qualquer quantidade e ecossistema.":["CONTEXT_FREE_LIMITATION"]},"position":8},{"id":"v5-bio-eco-transfer-01","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"CORREGO_URBANO_TERMICO","statement":"Em um riacho, pesquisadores medem temperatura e macroinvertebrados a montante e a jusante de um trecho sem mata ciliar, repetindo as coletas por várias semanas. A jusante fica mais quente e alguns grupos diminuem, enquanto o trecho de referência permanece estável. Qual conclusão é mais defensável?","options":["A ausência de mata é comprovadamente a única causa possível para toda mudança observada.","A estabilidade do trecho de referência prova que temperatura não afeta organismos.","O padrão apoia a hipótese de que a perda de sombra contribui para o aquecimento e a mudança biológica; outros fatores e o método de coleta ainda devem ser verificados.","Uma única medição já permite afirmar que todas as espécies do riacho desapareceram."],"correctAnswer":"O padrão apoia a hipótese de que a perda de sombra contribui para o aquecimento e a mudança biológica; outros fatores e o método de coleta ainda devem ser verificados.","explanation":"Medições repetidas e um trecho de referência fortalecem a comparação, mas diferenças de vazão, poluição, substrato e esforço amostral também podem importar.","hint":"Use a comparação espacial e temporal, mas confira se outras condições variaram junto.","errorFocus":"CONTROLLED_COMPARISON_TREATED_AS_CERTAINTY","misconceptions":{"A ausência de mata é comprovadamente a única causa possível para toda mudança observada.":["ALTERNATIVE_CAUSES_IGNORED"]},"position":1},{"id":"v5-bio-eco-transfer-02","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"POLINIZACAO_HORTA_SECA","statement":"Em uma horta, a contagem de visitas de abelhas e a produção de frutos caem no mesmo mês de estiagem. Qual dado adicional ajudaria mais a avaliar se a redução de visitas contribuiu para a produção?","options":["Contar apenas as abelhas em um dia de chuva no ano seguinte.","Medir a cor dos frutos já colhidos sem registrar quantas flores havia.","Perguntar se as abelhas preferem jardins de outra cidade.","Comparar flores com acesso livre e flores protegidas de visitantes, mantendo condições semelhantes e registrando água, floração e formação de frutos."],"correctAnswer":"Comparar flores com acesso livre e flores protegidas de visitantes, mantendo condições semelhantes e registrando água, floração e formação de frutos.","explanation":"Uma comparação planejada pode separar a contribuição de visitantes de efeitos da seca sobre as flores e a produção. O protocolo ainda deve respeitar o bem-estar dos organismos.","hint":"Procure uma comparação que altere o acesso dos polinizadores e registre outros efeitos da seca.","errorFocus":"CORRELATION_PROVES_SINGLE_CAUSE","misconceptions":{"Contar apenas as abelhas em um dia de chuva no ano seguinte.":["UNMATCHED_TIME_AND_CONDITION"]},"position":2},{"id":"v5-bio-eco-transfer-03","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"INTERPRET","contextFamily":"MANGUEZAL_GRADIENTE_SALINO","statement":"Ao longo de um manguezal, a salinidade aumenta da margem do rio para uma área mais aberta. Duas espécies de plantas apresentam distribuições diferentes nesse gradiente. Qual explicação deve orientar a próxima análise?","options":["A espécie mais distante do rio necessariamente causou o aumento da salinidade.","Como ambas são plantas, suas tolerâncias devem ser idênticas.","A salinidade pode contribuir para a distribuição, mas inundação, sedimento, luz e interações também precisam ser comparados.","A distribuição observada elimina a possibilidade de qualquer outro fator ambiental."],"correctAnswer":"A salinidade pode contribuir para a distribuição, mas inundação, sedimento, luz e interações também precisam ser comparados.","explanation":"Um gradiente mostra associação espacial e gera hipóteses; outros fatores que variam com a posição podem explicar parte do padrão.","hint":"Liste condições que mudam junto com a distância da margem.","errorFocus":"GRADIENT_CONFOUNDED_WITH_CAUSALITY","misconceptions":{"A espécie mais distante do rio necessariamente causou o aumento da salinidade.":["SPATIAL_ASSOCIATION_REVERSED_AS_CAUSE"]},"position":3},{"id":"v5-bio-eco-transfer-04","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"FRAGMENTACAO_CERRADO","statement":"Após a abertura de uma estrada, uma equipe encontra menos plantas jovens na borda de fragmentos do Cerrado do que no interior. Qual plano de investigação é mais forte para avaliar a relação com a fragmentação?","options":["Contar uma única planta na borda e concluir que a estrada eliminou a população inteira.","Repetir amostragens padronizadas em várias bordas e interiores, medir luz, umidade e perturbações e comparar fragmentos de tamanhos diferentes.","Comparar uma borda recém-aberta com uma floresta distante de outro clima, sem controlar diferenças.","Usar somente o número de carros na estrada como medida da regeneração vegetal."],"correctAnswer":"Repetir amostragens padronizadas em várias bordas e interiores, medir luz, umidade e perturbações e comparar fragmentos de tamanhos diferentes.","explanation":"Replicação, protocolo consistente e medição de mecanismos plausíveis ajudam a avaliar padrões de borda e outras diferenças entre áreas.","hint":"Combine repetição, comparação equivalente e medidas de condições que podem mediar o efeito.","errorFocus":"SINGLE_SITE_OVERGENERALIZATION","misconceptions":{"Contar uma única planta na borda e concluir que a estrada eliminou a população inteira.":["SAMPLE_GENERALIZED_TO_POPULATION"]},"position":4},{"id":"v5-bio-eco-transfer-05","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"RECIFE_ESTRESSE_TERMICO","statement":"Em um recife, episódios de branqueamento coincidem com semanas de água mais quente. Em alguns locais, a intensidade difere e também há registros distintos de turbidez. Que interpretação é mais rigorosa?","options":["A coincidência prova que a turbidez nunca influencia corais.","O aquecimento é uma hipótese relevante, mas comparar duração do calor, turbidez, profundidade e locais de referência ajuda a avaliar diferenças.","Branqueamento significa que todos os organismos do recife morreram.","A temperatura é um fator biótico porque os corais responderam a ela."],"correctAnswer":"O aquecimento é uma hipótese relevante, mas comparar duração do calor, turbidez, profundidade e locais de referência ajuda a avaliar diferenças.","explanation":"A associação temporal sugere um mecanismo, mas a distribuição desigual do efeito pode envolver condições locais e outras pressões; branqueamento não equivale automaticamente à morte de todos os organismos.","hint":"Separe a condição abiótica observada, a resposta e as diferenças entre locais.","errorFocus":"STRESSOR_AS_SOLE_CAUSE","misconceptions":{"Branqueamento significa que todos os organismos do recife morreram.":["RESPONSE_INDICATOR_CONFUSED_WITH_TOTAL_MORTALITY"]},"position":5},{"id":"v5-bio-eco-transfer-06","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"PREDICT","contextFamily":"BARRAGEM_FLUXO_RIO","statement":"Após a operação de uma barragem, a vazão diária de um trecho passa a variar menos. A equipe quer avaliar efeitos sobre organismos aquáticos. Qual conjunto de dados é mais informativo?","options":["Séries antes e depois de vazão, temperatura, oxigênio, habitat e abundância de grupos, incluindo um trecho comparável não afetado.","Apenas a altura da barragem medida uma vez.","Somente a opinião de um pescador sobre uma espécie em um dia.","A quantidade de água armazenada, sem observações do trecho ou de organismos."],"correctAnswer":"Séries antes e depois de vazão, temperatura, oxigênio, habitat e abundância de grupos, incluindo um trecho comparável não afetado.","explanation":"Séries temporais e local de referência permitem examinar mecanismos e separar mudanças associadas à operação de variações regionais.","hint":"Meça a alteração física, respostas biológicas e um local de comparação ao longo do tempo.","errorFocus":"BIOLOGICAL_EFFECT_WITHOUT_BASELINE","misconceptions":{"A quantidade de água armazenada, sem observações do trecho ou de organismos.":["INFRASTRUCTURE_METRIC_SUBSTITUTES_ECOSYSTEM_EVIDENCE"]},"position":6},{"id":"v5-bio-eco-lock-01","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"CLASSIFY","contextFamily":"NIVEIS_ECOLOGICOS_LAGOA","statement":"Uma equipe observa três espécies de peixes, algas, temperatura e oxigênio dissolvido em uma lagoa. Qual objeto de estudo inclui todos esses dados em conjunto?","options":["Uma população, porque qualquer conjunto observado em um local pertence à mesma espécie.","O ecossistema, porque inclui comunidades de organismos e condições abióticas.","Um organismo, porque a lagoa funciona como um indivíduo.","Uma comunidade, que inclui necessariamente as condições químicas da água."],"correctAnswer":"O ecossistema, porque inclui comunidades de organismos e condições abióticas.","explanation":"Uma comunidade reúne populações de diferentes espécies; ao incluir fatores físicos e químicos, o recorte é ecossistêmico.","hint":"Veja se o recorte inclui apenas organismos ou também o ambiente não vivo.","errorFocus":"LEVEL_OF_ORGANIZATION_ERROR","misconceptions":{"Uma comunidade, que inclui necessariamente as condições químicas da água.":["COMMUNITY_INCLUDES_ABIOTIC_COMPONENTS"]},"position":1},{"id":"v5-bio-eco-lock-02","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"COMPARE","contextFamily":"ENERGIA_CICLO_CARBONO","statement":"Em um modelo, setas alimentares mostram transferência de energia; outro esquema acompanha átomos de carbono entre atmosfera, plantas, animais e decompositores. Qual comparação está correta?","options":["Energia e carbono retornam intactos ao ponto inicial em cada alimentação.","O carbono só se move entre animais e nunca passa pelo ambiente.","A energia é matéria e por isso forma ciclos idênticos aos do carbono.","A energia é transferida e parte se dissipa; o carbono pode circular entre organismos e ambiente."],"correctAnswer":"A energia é transferida e parte se dissipa; o carbono pode circular entre organismos e ambiente.","explanation":"Os modelos representam processos diferentes: fluxo de energia e circulação de matéria. A energia não se recicla como os átomos de carbono.","hint":"Acompanhe o destino de uma parcela de energia e de um átomo de carbono separadamente.","errorFocus":"ENERGY_CYCLE_CONFUSED_WITH_MATTER_CYCLE","misconceptions":{"Energia e carbono retornam intactos ao ponto inicial em cada alimentação.":["ENERGY_RECYCLED_WITH_MATTER"]},"position":2},{"id":"v5-bio-eco-lock-03","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"AMOSTRAGEM_ANFIBIOS","statement":"Durante uma noite chuvosa, uma estudante observa um único anfíbio fora de uma poça e relata o local de encontro. O que esse registro permite concluir diretamente?","options":["Um indivíduo foi observado naquele local e momento; tendências populacionais exigem amostragens repetidas e representativas.","A população inteira aumentou naquela noite.","A chuva foi comprovadamente a única causa do deslocamento.","A espécie deixou de depender das condições abióticas."],"correctAnswer":"Um indivíduo foi observado naquele local e momento; tendências populacionais exigem amostragens repetidas e representativas.","explanation":"O registro individual é uma observação localizada. Não estima sozinho abundância nem prova a causa do comportamento.","hint":"Diferencie a unidade observada da população que se quer descrever.","errorFocus":"INDIVIDUAL_EQUALS_POPULATION","misconceptions":{"A população inteira aumentou naquela noite.":["SINGLE_OBSERVATION_AS_POPULATION_TREND"]},"position":3},{"id":"v5-bio-eco-lock-04","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"COMPETICAO_NINHOS","statement":"Duas espécies de aves usam cavidades semelhantes para nidificar. Em anos com poucas cavidades, uma espécie ocupa mais cavidades quando a outra é temporariamente ausente; em anos com muitas cavidades, a diferença diminui. Qual interpretação é mais sustentada?","options":["A ausência de uma espécie prova que a outra se alimenta dela.","O padrão é compatível com competição por cavidades quando o recurso é escasso, mas outras diferenças entre anos também devem ser consideradas.","Como as aves são diferentes, não podem competir por um recurso compartilhado.","O resultado demonstra que a disponibilidade de cavidades não afeta a ocupação."],"correctAnswer":"O padrão é compatível com competição por cavidades quando o recurso é escasso, mas outras diferenças entre anos também devem ser consideradas.","explanation":"Uso de um recurso limitado e resposta à ausência de uma espécie são compatíveis com competição; a comparação entre anos pode incluir outras mudanças ambientais.","hint":"Observe o recurso compartilhado e se a resposta muda quando ele é abundante ou escasso.","errorFocus":"COMPETITION_RESOURCE_CONTEXT_IGNORED","misconceptions":{"Como as aves são diferentes, não podem competir por um recurso compartilhado.":["COMPETITION_REQUIRES_SAME_SPECIES"]},"position":4},{"id":"v5-bio-eco-review-01","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"PREDICT","contextFamily":"PRODUTOR_TURBIDEZ","statement":"Uma descarga de sedimentos deixa a água temporariamente mais turva em um lago e reduz a luz em plantas aquáticas. Qual efeito inicial é plausível, sem ser inevitável para todas as espécies?","options":["A turbidez transforma plantas em consumidores de outros peixes.","A menor luz faz a matéria desaparecer do lago.","A produção fotossintética de algumas plantas pode diminuir, alterando recursos disponíveis a outros organismos.","A mudança garante que todas as populações aumentem na mesma proporção."],"correctAnswer":"A produção fotossintética de algumas plantas pode diminuir, alterando recursos disponíveis a outros organismos.","explanation":"Menor luz pode limitar a fotossíntese de organismos fotossintetizantes; efeitos posteriores dependem das espécies, da duração e de outras condições.","hint":"Conecte luz, produção primária e recursos sem presumir resposta uniforme.","errorFocus":"UNIFORM_RESPONSE_ASSUMED","misconceptions":{"A mudança garante que todas as populações aumentem na mesma proporção.":["ECOSYSTEM_RESPONSE_ASSUMED_UNIFORM"]},"position":1},{"id":"v5-bio-eco-review-02","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"INTERPRET","contextFamily":"TRANSFERENCIA_NIVEL_TROFICO","statement":"Um modelo indica 1.000 unidades de energia produzida por plantas e 120 unidades incorporadas à produção de consumidores primários no mesmo período. Qual afirmação respeita o alcance do modelo?","options":["Exatamente 880 unidades foram destruídas e não podem aparecer em nenhum outro processo.","Os consumidores primários produziram as 1.000 unidades inicialmente captadas pelas plantas.","O modelo registra transferência de parte da energia para a produção dos consumidores; o restante pode ter destinos como respiração, calor, material não consumido e decomposição.","Toda a matéria do ecossistema foi transferida junto com as 120 unidades de energia."],"correctAnswer":"O modelo registra transferência de parte da energia para a produção dos consumidores; o restante pode ter destinos como respiração, calor, material não consumido e decomposição.","explanation":"A diferença entre valores não equivale a energia simplesmente destruída. A energia pode seguir diferentes vias, e o diagrama precisa especificar os compartimentos incluídos.","hint":"Não trate a diferença entre dois compartimentos como um destino único sem dados.","errorFocus":"ENERGY_DIFFERENCE_AS_DISAPPEARANCE","misconceptions":{"Exatamente 880 unidades foram destruídas e não podem aparecer em nenhum outro processo.":["ENERGY_DESTROYED_OR_UNACCOUNTED"]},"position":2},{"id":"v5-bio-eco-review-03","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"CLASSIFY","contextFamily":"PARASITISMO_FOLHAS","statement":"Uma planta hospedeira apresenta perda de nutrientes enquanto um organismo vive sobre ela e obtém alimento. Qual descrição caracteriza melhor a interação, se os efeitos forem confirmados?","options":["Parasitismo: o organismo obtém benefício e o hospedeiro sofre prejuízo.","Mutualismo: ambos necessariamente se beneficiam porque estão associados.","Competição: os dois organismos disputam sempre o mesmo alimento.","Comensalismo: o hospedeiro recebe benefício comprovado e o outro não é afetado."],"correctAnswer":"Parasitismo: o organismo obtém benefício e o hospedeiro sofre prejuízo.","explanation":"A classificação depende dos efeitos nos dois parceiros. O cenário descreve benefício de um e prejuízo do hospedeiro, padrão de parasitismo.","hint":"Avalie separadamente o efeito da interação sobre cada parceiro.","errorFocus":"INTERACTION_SIGNS_CONFUSED","misconceptions":{"Mutualismo: ambos necessariamente se beneficiam porque estão associados.":["ASSOCIATION_ASSUMED_MUTUALISTIC"]},"position":3},{"id":"v5-bio-eco-review-04","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"ESPACAMENTO_PLANTAS","statement":"Em uma área, plantas adultas aparecem aproximadamente espaçadas. Qual investigação ajudaria a distinguir competição por recursos de outras explicações para esse padrão?","options":["Concluir competição apenas porque as plantas não estão agrupadas.","Contar flores em uma única planta e inferir a distribuição de todas as sementes.","Medir a cor do solo em um ponto sem registrar posições das plantas.","Medir recursos e sobrevivência em diferentes densidades, comparar parcelas e verificar se o espaçamento muda quando a disponibilidade de recursos é alterada."],"correctAnswer":"Medir recursos e sobrevivência em diferentes densidades, comparar parcelas e verificar se o espaçamento muda quando a disponibilidade de recursos é alterada.","explanation":"Um padrão espacial pode resultar de competição, dispersão, condições locais ou outras interações; manipulação e medidas comparáveis ajudam a distinguir mecanismos.","hint":"Procure testar como o padrão responde à densidade e à disponibilidade do recurso proposto.","errorFocus":"PATTERN_AS_MECHANISM_PROOF","misconceptions":{"Concluir competição apenas porque as plantas não estão agrupadas.":["SPATIAL_PATTERN_PROVES_CAUSE"]},"position":4},{"id":"v5-bio-eco-review-05","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"PESTICIDA_INDICADOR","statement":"Após uma aplicação de pesticida em uma região agrícola, uma espécie de inseto é menos observada. Qual abordagem apoia melhor uma avaliação do efeito?","options":["Atribuir a diferença ao produto com base em uma contagem feita em um único dia.","Comparar somente o número de insetos com a produção agrícola de outro estado.","Usar contagens repetidas com protocolo constante em áreas tratadas e comparáveis não tratadas, medindo também clima, habitat e outras pressões.","Considerar a ausência de registros como prova de extinção local imediata."],"correctAnswer":"Usar contagens repetidas com protocolo constante em áreas tratadas e comparáveis não tratadas, medindo também clima, habitat e outras pressões.","explanation":"Repetição, comparação e registro de fatores alternativos tornam a inferência mais confiável; uma observação isolada não determina a causa.","hint":"Pense em linha de base, controle comparável e consistência de amostragem.","errorFocus":"POST_EVENT_SINGLE_COUNT","misconceptions":{"Atribuir a diferença ao produto com base em uma contagem feita em um único dia.":["BEFORE_AFTER_CAUSALITY_ASSUMED"]},"position":5},{"id":"v5-bio-eco-review-06","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"EXPLAIN","contextFamily":"DECOMPOSICAO_NUTRIENTES","statement":"Após a queda de folhas, organismos do solo fragmentam o material e liberam compostos que podem ser absorvidos por plantas. Qual processo essa descrição destaca?","options":["A reciclagem integral de toda energia sem dissipação.","A transformação e circulação de matéria entre componentes bióticos e abióticos.","A interrupção da produção primária por qualquer decompositor.","A conversão de plantas em fatores abióticos antes de ocorrer decomposição."],"correctAnswer":"A transformação e circulação de matéria entre componentes bióticos e abióticos.","explanation":"A decomposição transforma matéria orgânica e pode disponibilizar elementos no ambiente; depois, organismos podem incorporá-los novamente.","hint":"Siga os elementos químicos da folha para o solo e, depois, para uma planta.","errorFocus":"MATTER_CYCLE_STEP_MISSING","misconceptions":{"A reciclagem integral de toda energia sem dissipação.":["ENERGY_AND_MATTER_CONFLATED"]},"position":6},{"id":"v5-bio-eco-review-07","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"PREDICT","contextFamily":"REDE_PREDADORES_ALTERNATIVOS","statement":"Em uma teia, uma espécie de predador consome duas espécies de herbívoros, e ambas também são consumidas por outro predador. Se o primeiro predador diminuir, qual previsão é mais prudente?","options":["Os herbívoros necessariamente dobrarão porque existe apenas uma relação na teia.","O outro predador deixará de consumir suas presas por causa da ausência do primeiro.","A teia alimentar deixa de existir assim que uma população muda.","A pressão de predação sobre os herbívoros pode mudar, mas a resposta dependerá também do segundo predador, dos recursos e de outras relações."],"correctAnswer":"A pressão de predação sobre os herbívoros pode mudar, mas a resposta dependerá também do segundo predador, dos recursos e de outras relações.","explanation":"A teia contém caminhos alternativos e fatores adicionais. Uma previsão deve indicar o mecanismo plausível sem transformar a resposta em certeza quantitativa.","hint":"Siga todos os caminhos que chegam às duas presas, não apenas uma seta.","errorFocus":"FOOD_WEB_REDUCED_TO_SINGLE_CHAIN","misconceptions":{"Os herbívoros necessariamente dobrarão porque existe apenas uma relação na teia.":["NETWORK_EFFECT_ASSUMED_LINEAR"]},"position":7},{"id":"v5-bio-eco-review-08","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"SYNTHESIZE","contextFamily":"SERIE_TEMPORAL_RIO","statement":"Em um rio, quatro meses de dados mostram chuva menor, temperatura maior e queda de um grupo de organismos. Qual síntese é mais adequada para um relatório inicial?","options":["Os dados provam que a falta de chuva eliminou todo o grupo em toda a bacia.","A série registra mudanças concomitantes e permite formular hipóteses; comparar vazão, oxigênio, habitat, esforço de coleta e locais de referência ajudará a avaliar mecanismos.","A temperatura não pode ter relação com organismos porque é abiótica.","A queda do grupo prova que os organismos causaram a redução da chuva."],"correctAnswer":"A série registra mudanças concomitantes e permite formular hipóteses; comparar vazão, oxigênio, habitat, esforço de coleta e locais de referência ajudará a avaliar mecanismos.","explanation":"A série temporal mostra padrões conjuntos, mas não separa sozinha causalidade. Medidas adicionais e comparações ampliam a força da interpretação.","hint":"Escreva uma frase sobre o observado e outra sobre o que ainda precisa ser testado.","errorFocus":"TEMPORAL_COVARIATION_AS_CAUSAL_PROOF","misconceptions":{"Os dados provam que a falta de chuva eliminou todo o grupo em toda a bacia.":["LOCAL_SHORT_SERIES_GENERALIZED"]},"position":8}]'::jsonb) as item(
      id text, purpose text, difficulty text, "cognitiveProcess" text,
      "contextFamily" text, statement text, options jsonb, "correctAnswer" text,
      explanation text, hint text, "errorFocus" text, misconceptions jsonb, position integer
    )
  loop
    insert into public.learning_question_sets(scope, canonical_skill_id, purpose, version, active, metadata)
    values ('GLOBAL', v_skill_id, v_question.purpose, 5, false,
      jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', 'v5-biology-ecosystem-interactions',
        'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING', 'publication_status', 'STAGING',
        'bncc_alignment_status', 'NOT_CLAIMED'))
    on conflict (canonical_skill_id, purpose, version) where scope = 'GLOBAL' do nothing;
    select id into v_set_id from public.learning_question_sets
     where scope = 'GLOBAL' and canonical_skill_id = v_skill_id
       and purpose = v_question.purpose and version = 5
       and metadata->>'content_id' = 'v5-biology-ecosystem-interactions' and active = false;
    if v_set_id is null then raise exception 'V5_CONTENT_QUESTION_SET_CONFLICT'; end if;

    select id into v_question_id from public.learning_question_bank
     where source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING' and metadata->>'content_id' = v_question.id;
    if v_question_id is null then
      insert into public.learning_question_bank(
        package_type, source_type, source_name, subject_area, domain, topic,
        statement, options, correct_answer, explanation, difficulty,
        estimated_minutes, provenance, metadata, active
      ) values (
        'TECESCOLA', 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING', 'TecEscola Question First V5 - Staging',
        'BIOLOGY', 'ECOLOGIA', 'interacoes em ecossistemas',
        v_question.statement, v_question.options, to_jsonb(v_question."correctAnswer"),
        v_question.explanation, v_question.difficulty, 2,
        'TECESCOLA_CORE_V5_AUTHORED',
        jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', v_question.id,
          'purpose', v_question.purpose, 'context_family', v_question."contextFamily",
          'cognitive_process', v_question."cognitiveProcess", 'error_focus', v_question."errorFocus",
          'remediation_hint', v_question.hint, 'misconceptions', v_question.misconceptions,
          'content_authoring_status', 'AUTHORED', 'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING',
          'publication_status', 'STAGING', 'bncc_alignment_status', 'NOT_CLAIMED'), false
      ) returning id into v_question_id;
    end if;
    if v_question_id is null then raise exception 'V5_CONTENT_QUESTION_INSERT_FAILED'; end if;
    update public.learning_question_bank set active = false
     where id = v_question_id and source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING';
    insert into public.learning_question_bank_skill_links(question_bank_id, canonical_skill_id, skill_role)
    values (v_question_id, v_skill_id, 'PRIMARY') on conflict (question_bank_id, canonical_skill_id) do nothing;
    insert into public.learning_question_set_items(question_set_id, question_bank_id, position)
    values (v_set_id, v_question_id, v_question.position)
    on conflict (question_set_id, question_bank_id) do nothing;
  end loop;
end;
$seed_question_first_content_v5$;

commit;
